type Config struct {
	Host    string
	Port    int
	Tags    []string
	Limits  map[string]int
	Timeout time.Duration
}

var c Config
// c.Host    == ""
// c.Port    == 0
// c.Tags    == nil   (append is fine)
// c.Limits  == nil   (writing panics)
// c.Timeout == 0

s := "héllo"

len(s)            // 6  - BYTES, not characters
[]byte(s)         // the 6 raw bytes
[]rune(s)         // 5  - code points
len([]rune(s))    // 5

for i, r := range s {
	// i jumps 0,1,3,4,5 - byte offsets
	// r is a rune (int32)
}

